#!/usr/bin/env python3
# luxarch:worktree-land hook v1 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""`worktree.py land`: land the issue branch of the worktree it runs in on the base branch, as
a fast-forward only, after the checks that keep it from losing anyone's work: the worktree holds
nothing git does not, the main checkout is on the base and holds no change of the owner's, the
branch is rebased on the base it lands on, and no path it adds overwrites a file git does not hold
in the owner's checkout. Under `[agents] push = "agent"` it first takes origin's base (a fast-forward
only; a rewritten or diverged origin is the owner's), fast-forwards the owner's checkout, and then
pushes: the push is the compare-and-swap, and when origin does not take it the local base is put
back. Whatever keeps the owner's checkout from moving refuses before origin is told anything. It
prints each landed commit as the close-out records it.

Python 3.9 and the standard library only, like the hook that loads it.
"""

from __future__ import annotations

import contextlib
import fcntl
import json
import os
import shlex
import subprocess
import sys
import time
from pathlib import Path

from _worktree_git import (
    base_branch,
    checked_out,
    count,
    main_checkout,
    net_limit,
    out,
    push_mode,
    remote_tip,
    run,
    run_net,
)
from _worktree_sessions import clear_session
from _worktree_submodules import main_changes
from _worktree_work import blockers, mid_operation, mounting, running_mounts

# land's exit for a refusal no branch caused, with nothing changed: the owner's checkout refuses
# the fast-forward (an edit git hides, a held index lock, the owner's signature policy), or origin
# cannot be synced (unreachable, rewritten, diverged from the local base). The land queue stops on
# it instead of blaming a branch
OWNER_REFUSED = 3
# land's exit when another land in this repository on this machine is running: the land queue stops
# on it too
LAND_BUSY = 4
# land's exit for a refusal the branch itself caused, with nothing changed: a rebase onto the base
# conflicts, it adds a path over a file the owner's checkout holds outside git, its commit lacks the
# signature the owner's merge requires, or origin's own rules reject it. The land queue hands a
# branch back only on this exit; on any other refusal it stops, every branch still ready.
BRANCH_REFUSED = 5
# land's exit for a push refused while origin's base stayed where land pushed onto: by this repo's
# own pre-push hook or by origin. Whether the branch's content or the environment caused it (a
# secret scan, or a hook down for maintenance) the refusal cannot say; the land queue hands the
# branch back with the refusal quoted, and its agent runs `ready` again when the content is not the
# cause. Land returns it only after a second push failed the same way: a connection that dropped
# once goes through on the retry.
PUSH_REFUSED = 6
# one land at a time per repository on a machine, from origin's sync through the push and the
# fast-forward: two lands would otherwise sync, push and fast-forward interleaved
LAND_LOCK = "luxarch-land.lock"


def cmd_land(also: tuple[str, ...] = ()) -> int:
    """Land this worktree's branch, holding the repository's land lock throughout. `also`: the land
    queue's other branch heads this run, whose submodule pins the main checkout may sit at without
    that being the owner's change."""
    here = Path(out(Path.cwd(), "rev-parse", "--show-toplevel") or Path.cwd())
    main = main_checkout(here)
    if main is None:
        print("not inside a git checkout with a .git directory", file=sys.stderr)
        return 2
    try:
        # not inherited by the hooks a land runs (Python opens it non-inheritable), so a land a
        # pre-push hook starts is a second land
        # created as the umask and the repository's sharing allow, so every account that may land
        # in a shared repository can open it; opened for writing, since an NFS client takes an
        # exclusive flock as a write lock (EBADF on a read-only descriptor), and read-only only
        # where this account may not write a lock another account made
        path = main / ".git" / LAND_LOCK
        try:
            fd = os.open(path, os.O_RDWR | os.O_CREAT, 0o666)
        except PermissionError:
            fd = os.open(path, os.O_RDONLY)
    except OSError as e:
        print(f"REFUSING: cannot open the land lock: {e}", file=sys.stderr)
        return 1
    try:
        try:
            fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError:
            print(
                "REFUSING: another land in this repository is running on this machine; nothing "
                "changed. Run land again when it has finished.",
                file=sys.stderr,
            )
            return LAND_BUSY
        except OSError as e:
            # a filesystem that cannot lock says so; it is not a land in progress
            print(f"REFUSING: cannot take the land lock: {e}", file=sys.stderr)
            return 1
        return _land(here, main, also)
    finally:
        os.close(fd)


def _land(here: Path, main: Path, also: tuple[str, ...]) -> int:
    if here == main:
        print(
            "REFUSING: land runs inside the issue's worktree, not the main checkout. "
            "Enter it first (EnterWorktree name=<ISSUE-KEY>).",
            file=sys.stderr,
        )
        return 2
    branch = out(here, "symbolic-ref", "--quiet", "--short", "HEAD")
    base = base_branch(main)
    if not branch:
        print("REFUSING: the worktree must be on its issue's branch", file=sys.stderr)
        return 2
    if checked_out(main) != base:
        print(
            f"REFUSING: the main checkout ({main}) is not on {base}, the default branch, so a "
            "fast-forward would land this issue somewhere else. It is the owner's checkout: tell the "
            f"owner, and land once it is back on {base}.",
            file=sys.stderr,
        )
        return 1
    # an exact copy of the main checkout's ignored file is not work (Claude Code copies its
    # settings.local.json into every worktree it creates)
    held = blockers(here, main)
    if held:
        shown = "".join(f"  {line}\n" for line in held[:20])
        more = f"  ... and {len(held) - 20} more\n" if len(held) > 20 else ""
        print(
            f"REFUSING: {here} has uncommitted changes: commit them (or remove what is not yours to ship), then land.\n"
            f"{shown}{more}"
            "An ignored file a build regenerates (a built asset, a stamp) is removed with a plain `rm <file>`; "
            "a tool's cache directory never blocks.",
            file=sys.stderr,
        )
        return 1
    # a submodule main has checked out at the gitlink this branch pins is not work: a pin bump
    # needs the main checkout's submodule at the new pin for the repo's own hooks
    dirty = main_changes(main, here, also)
    if dirty:
        shown = "".join(f"  {d}\n" for d in dirty[:20])
        more = f"  ... and {len(dirty) - 20} more\n" if len(dirty) > 20 else ""
        print(
            f"REFUSING: the main checkout ({main}) has uncommitted changes to tracked files. It is the "
            f"owner's checkout: tell the owner, and land once it is clean.\n{shown}{more}",
            file=sys.stderr,
        )
        return 1
    # a merge, rebase or cherry-pick the owner left in progress: nothing may be pushed while main
    # cannot fast-forward after it (`merge --ff-only` refuses an unconcluded merge)
    busy = mid_operation(main)
    if busy:
        print(
            f"REFUSING: the main checkout ({main}) has a git operation in progress ({busy}). It is "
            "the owner's checkout: tell the owner, and land once it is concluded or aborted.",
            file=sys.stderr,
        )
        return 1
    local = f"refs/heads/{base}"
    remote = f"refs/remotes/origin/{base}"
    # `[agents] push = "agent"`: land against origin, not only this machine. An agent elsewhere may
    # have pushed since this worktree branched, so the local base first takes origin's.
    pushing = push_mode(main) == "agent" and bool(
        out(main, "remote", "get-url", "origin")
    )
    hold = push_hold(main)
    if pushing and hold:
        # a recorded hold (unpushed-stop-guard's): nothing is pushed while it stands
        print(f"Push held (.claude/.push-hold): {hold}. Landing locally only.")
        pushing = False
    if pushing:
        refused = sync_with_origin(main, base)
        if refused:
            # origin unreachable or rewritten, the local base diverged from it, or the owner's
            # checkout refused origin's base: no branch's doing, so the land queue blames none
            print(refused, file=sys.stderr)
            return OWNER_REFUSED
    new = count(here, f"HEAD..{local}")
    if new and run(here, "merge-base", "--is-ancestor", "HEAD", local).returncode == 0:
        # the base already holds this branch whole (a landing origin took earlier, perhaps with
        # another agent's push on top): nothing to rebase, nothing to gate again
        new = 0
    if new:
        r = run(here, "rebase", local)
        if r.returncode != 0:
            run(here, "rebase", "--abort")
            print(
                f"REFUSING: rebasing {branch} onto {base} conflicts; nothing changed. Resolve it here "
                f"(`git rebase {base}`, fix, `git rebase --continue`), re-run the gate, then land.\n"
                + (r.stdout + r.stderr).strip(),
                file=sys.stderr,
            )
            return BRANCH_REFUSED
        print(
            f"Rebased {branch} onto {new} new commit(s) from {base}. What you tested is not what would "
            "land: re-run the touched tests and the gate here, then run land again.",
            file=sys.stderr,
        )
        return 1
    ahead = count(here, f"{local}..HEAD")
    issue_commits = out(here, "rev-list", "--reverse", f"{local}..HEAD").split()
    # A path the issue adds that already exists, untracked or ignored, in the owner's checkout: git
    # treats an ignored file as expendable and the fast-forward overwrites it (an owner's `.env`).
    held = held_files(main, added_paths(here, f"{local}...HEAD"))
    if held:
        print(
            f"REFUSING: this issue adds {', '.join(held[:5])}, which already exist in the owner's "
            "checkout as files git does not hold; landing would overwrite them. Tell the owner.",
            file=sys.stderr,
        )
        return BRANCH_REFUSED
    # what origin lacks: the issue's commits, and landed commits the local base holds unpushed
    unpushed = 0
    if pushing:
        known = out(main, "rev-parse", "--verify", "--quiet", remote)
        unpushed = count(here, f"{remote}..HEAD") if known else 1
        if not issue_commits and unpushed and known:
            # the base already holds the branch (an owner's local merge): the commits this push
            # adds are what lands on origin
            issue_commits = out(
                here, "rev-list", "--reverse", f"{remote}..HEAD"
            ).split()
    if not ahead and not unpushed:
        written = pending_landing(main, branch)
        earlier = (
            written[1]
            if written
            and run(main, "merge-base", "--is-ancestor", written[0], local).returncode
            == 0
            else []
        )
        if earlier:
            print(
                f"Landed earlier: origin already held {len(earlier)} commit(s) of {branch} (a push "
                f"whose answer never came back), and the local {base} has them now."
            )
            clear_session(here)
            print(
                "Landed commits, one JSON object per line: the close-out's "
                "`luxpm_log_activity(commits=[...])` takes each verbatim."
            )
            for sha in earlier:
                print(json.dumps(commit_record(main, sha)))
            pending_landing(main, branch, clear=True)
            print(
                "Now remove the worktree: ExitWorktree action=keep, then from the main checkout "
                f"`python3 .claude/hooks/worktree.py list --prune` (it prunes {branch}: landed and "
                "clean). Never ExitWorktree remove with discard_changes."
            )
            return 0
        print(f"Nothing to land: {branch} has no commits that {base} lacks.")
        return 0
    head = out(here, "rev-parse", "HEAD")
    if ahead:
        # Asked of git before origin is told anything: will the owner's checkout take the
        # fast-forward? Pushed first and found out after, an edit git hides, a held index lock or
        # the owner's signature policy left origin holding a landing the base could not follow.
        refused = owner_refuses(main, local, head)
        if refused:
            print(
                f"REFUSING: the main checkout ({main}) cannot take the fast-forward of {base} to "
                f"{branch}; nothing changed, here or on origin. It is the owner's checkout: tell "
                f"the owner what git says.\n{refused}",
                file=sys.stderr,
            )
            return OWNER_REFUSED
        unsigned = signature_refuses(main, local, head)
        if unsigned:
            print(
                f"REFUSING: {branch} cannot land on {base}; nothing changed, here or on origin.\n"
                f"{unsigned}",
                file=sys.stderr,
            )
            return BRANCH_REFUSED
    if pushing:
        # the push is the compare-and-swap: origin takes it only as a fast-forward of what it holds
        was = out(main, "rev-parse", "--verify", "--quiet", remote)
        # written down before origin is told: a push whose answer never comes back still has its
        # records for the land that finds it landed. An earlier such landing the synced base
        # already holds rides along, so its records come with these.
        written = pending_landing(main, branch)
        if (
            written
            and run(main, "merge-base", "--is-ancestor", written[0], local).returncode
            == 0
        ):
            issue_commits = [
                c for c in written[1] if c not in issue_commits
            ] + issue_commits
        pending_landing(main, branch, (head, issue_commits))
        # A push that fails while origin's base stays put is tried once more: a connection that
        # dropped once goes through, and what fails twice (the branch's content, or origin or the
        # repo's pre-push hook refusing it) comes back quoted. Git's words are never parsed for it:
        # they are localized, and a refusal can read like a dropped connection (an HTTP 413).
        # Both attempts share the one push budget (`net_limit`): the repo's pre-push hook runs in
        # each, and the land lock is held throughout.
        deadline = time.monotonic() + net_limit(True)
        first = ""
        for attempt in (1, 2):
            left = deadline - time.monotonic()
            if attempt == 2 and left <= 0:
                # one failure is no verdict: nobody is blamed, and land runs again; origin
                # answered as unmoved, so nothing landed
                pending_landing(main, branch, clear=True)
                print(
                    f"REFUSING: the push of {branch} to {base} failed once and no time is left in "
                    f"the push budget ({net_limit(True):g}s) to try again; nothing landed. Run "
                    f"land again.\n{first}",
                    file=sys.stderr,
                )
                return 1
            # the vetted commit by its sha, never `HEAD`: the repo's own pre-push hook may commit on
            # the branch, and a retry would then push a commit no gate saw
            r = run_net(
                here,
                "push",
                "--quiet",
                "origin",
                f"{head}:{local}",
                push=True,
                limit=left,
            )
            if r.returncode == 124:
                # timed out: origin may still have taken it, so ask where its base is now
                tip = remote_tip(main, local)
                if tip == [head]:
                    r = subprocess.CompletedProcess(r.args, 0, "", "")
                elif origin_under(main, tip, head, was):
                    # origin's own side may still take a push it already received, so this is what
                    # origin held when asked, never a proof that the push will not land: the
                    # record stays for the land that finds it landed
                    print(
                        f"REFUSING: the push of {branch} to {base} ran past {net_limit(True):g}s, "
                        f"and origin had not taken it when asked (it held "
                        f"{(was or 'no ' + base)[:8]}). The push runs this repo's pre-push hook: if "
                        "that needs longer, set LUXARCH_LAND_PUSH_TIMEOUT=<seconds>. Run land "
                        "again: it fetches origin, and finishes or pushes again.\n"
                        + (r.stdout + r.stderr).strip(),
                        file=sys.stderr,
                    )
                    return 1
                else:
                    print(
                        f"REFUSING: the push of {branch} to {base} timed out, and origin's base "
                        "could not be confirmed; it may have landed there. Run land again: it "
                        "fetches origin and finishes, or reports nothing to land.\n"
                        + (r.stdout + r.stderr).strip(),
                        file=sys.stderr,
                    )
                    return 1
            if r.returncode == 0:
                break
            said = (r.stdout + r.stderr).strip()
            first = first or said
            tip = remote_tip(main, local)
            if tip == [head]:
                # origin took it, and the answer was lost on the way back (a dropped response): a
                # landing, so the fast-forward and the commit records follow
                r = subprocess.CompletedProcess(r.args, 0, "", "")
                break
            if not origin_under(main, tip, head, was):
                if tip is not None:
                    # origin answered, and holds something else: this push did not land
                    pending_landing(main, branch, clear=True)
                print(
                    f"REFUSING: the push of {branch} to {base} failed and origin "
                    + ("could not be asked" if tip is None else "moved meanwhile")
                    + "; nothing landed. Run land again: it fetches, rebases and stops for the "
                    f"gate. Never `git pull --rebase` on {base}.\n{said}",
                    file=sys.stderr,
                )
                return 1
            if attempt == 1:
                print(
                    f"The push of {branch} to {base} failed with origin's base unmoved; trying "
                    "once more.",
                    file=sys.stderr,
                )
                continue
            # the wording only: which side said no is no part of the verdict
            who = (
                "origin rejected"
                if "[remote rejected]" in said or "[rejected]" in said
                else "this repo's pre-push hook or origin refused"
            )
            print(
                f"REFUSING: {who} the push of {branch} to {base} twice; nothing landed. Origin's base "
                "did not move: read what refused it below, fix the branch if its content is the "
                "cause, else run land again or tell the owner. Never `git pull --rebase` on "
                f"{base}.\n{said}",
                file=sys.stderr,
            )
            pending_landing(main, branch, clear=True)
            return PUSH_REFUSED
    if ahead:
        # only ever a fast-forward: it cannot drop a commit the base gained meanwhile (the owner's,
        # or another agent's landing); then it fails, and nothing on the base moves
        # `--no-squash`: the owner's `branch.<base>.mergeOptions` may squash, which writes the
        # tree and leaves the base where it was; and the base must end on what was pushed. To the
        # vetted sha, never the branch by name, which a hook may have moved past it.
        r = run(main, "merge", "--ff-only", "--no-squash", "--quiet", head)
        if (
            r.returncode == 0
            and out(main, "rev-parse", "--verify", "--quiet", local) != head
        ):
            r = subprocess.CompletedProcess(
                r.args, 1, "", f"{base} is not at {head[:8]} after the fast-forward"
            )
        if r.returncode != 0:
            print(
                f"REFUSING: {base} moved while landing, or the owner's checkout changed while it "
                f"pushed, so it cannot fast-forward to {branch}"
                + (
                    "; origin already holds the push. Run land again: it brings the local base up, "
                    "or says what in the owner's checkout keeps it from moving."
                    if pushing
                    else "; nothing changed. Run land again."
                )
                + f"\n{(r.stdout + r.stderr).strip()}",
                file=sys.stderr,
            )
            if pushing and issue_commits:
                # origin holds them: the close-out records them now, since the next land finds
                # nothing to land
                print(
                    "Landed on origin, one JSON object per line: the close-out's "
                    "`luxpm_log_activity(commits=[...])` takes each verbatim."
                )
                for sha in issue_commits:
                    print(json.dumps(commit_record(main, sha)))
                pending_landing(main, branch, clear=True)
            return 1
    # what landed: on origin under push = "agent" (the pushed head), else the local base
    short = (
        out(here, "rev-parse", "--short", "HEAD")
        if pushing
        else out(main, "rev-parse", "--short", base)
    )
    if pushing:
        print(
            f"Landed and pushed {max(ahead, unpushed)} commit(s) on {base} at {short}."
        )
        then = ""
    else:
        print(f"Landed {ahead} commit(s) on {base} at {short}.")
        then = f" Then push {base} as this repo's [agents] push declares."
    # the agent working here is done: its session's record no longer holds the worktree
    clear_session(here)
    if issue_commits:
        print(
            "Landed commits, one JSON object per line: the close-out's "
            "`luxpm_log_activity(commits=[...])` takes each verbatim."
        )
        for sha in issue_commits:
            print(json.dumps(commit_record(main, sha)))
    if pushing:
        pending_landing(main, branch, clear=True)
    users = mounting(here, running_mounts()[0])
    if users:
        print(
            f"WARNING: running container(s) {', '.join(users)} mount files in this worktree. "
            "`list --prune` keeps it while they run: deploy that stack from the main checkout "
            f"({main}), then prune."
        )
    # ExitWorktree's `remove` judges the branch against the commit it was made from, so it refuses
    # every landed branch as unmerged; `list --prune` judges it against the base and removes it.
    print(
        f"Now remove the worktree: ExitWorktree action=keep, then from the main checkout "
        f"`python3 .claude/hooks/worktree.py list --prune` (it prunes {branch}: landed and "
        f"clean). Never ExitWorktree remove with discard_changes.{then}"
    )
    return 0


# The files listed per landed commit; a commit touching more says so (`files_truncated`).
MAX_FILES = 200


def commit_record(main: Path, sha: str) -> dict[str, object]:
    """A landed commit as the tracker's commit link takes it: its sha, `committed_at` from git
    (`%cI`, never typed), and the files it touched (`--name-status -M`: a rename as its new path,
    with the old one beside it)."""
    files: list[dict[str, str]] = []
    raw = out(
        main,
        "diff-tree",
        "--root",
        "--no-commit-id",
        "-r",
        "-M",
        "--name-status",
        "-z",
        sha,
    ).split("\0")
    i = 0
    total = 0
    while i < len(raw) and raw[i]:
        status = raw[i]
        renamed = status[:1] in ("R", "C")
        paths = raw[i + 1 : i + (3 if renamed else 2)]
        i += 3 if renamed else 2
        if not paths:
            break
        total += 1
        if len(files) < MAX_FILES:
            entry = {"status": status[:1], "path": paths[-1]}
            if renamed and len(paths) == 2:
                entry["from"] = paths[0]
            files.append(entry)
    return {
        "sha": sha,
        "committed_at": out(main, "show", "-s", "--format=%cI", sha),
        "files": files,
        "files_truncated": total > len(files),
    }


# a push's landing, written before origin is told: `<git dir>/luxarch-landing/<branch>.json`
LANDING_DIR = "luxarch-landing"
# an unreadable or unparsable landing record is none (a tuple constant, so the formatter cannot
# rewrite the except into syntax the Python 3.9 on the owner's Mac refuses)
_RECORD_ERRORS = (OSError, ValueError)


def pending_landing(
    main: Path,
    branch: str,
    write: tuple[str, list[str]] | None = None,
    clear: bool = False,
) -> tuple[str, list[str]] | None:
    """The landing a push of `branch` left written down: (head, commits), or None. With `write`,
    record it (before the push); with `clear`, remove it (its records printed). Read from the main
    checkout's git dir, which every worktree shares, under the land lock."""
    path = (
        main
        / ".git"
        / LANDING_DIR
        / (branch.replace("%", "%25").replace("/", "%2F") + ".json")
    )
    if clear:
        with contextlib.suppress(OSError):
            path.unlink()
        return None
    if write is not None:
        with contextlib.suppress(OSError):
            path.parent.mkdir(exist_ok=True)
            path.write_text(
                json.dumps({"head": write[0], "commits": write[1]}), encoding="utf-8"
            )
        return None
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except _RECORD_ERRORS:
        return None
    head, commits = data.get("head"), data.get("commits")
    if not isinstance(head, str) or not isinstance(commits, list):
        return None
    return head, [str(c) for c in commits]


def origin_under(main: Path, tip: list[str] | None, head: str, was: str) -> bool:
    """Origin's base (`remote_tip`'s answer) is still what the branch sits on: a push that failed
    against it was refused, not overtaken. Judged by ancestry, never by the tracking ref (`was`),
    which any fetch on this machine moves: a non-fast-forward is origin having moved."""
    if tip is None:
        return False
    if not tip:
        return not was  # origin has no base, and had none: the push would create it
    return run(main, "merge-base", "--is-ancestor", tip[0], head).returncode == 0


def owner_refuses(main: Path, base_ref: str, new: str) -> str:
    """Why the main checkout would not take the fast-forward of `base_ref` to `new` ("" when it
    would), asked of git with nothing changed: a held index lock; the same two-tree update the
    fast-forward makes (`read-tree -m -u`), run dry against the owner's index and files, which
    refuses an edit it would overwrite, a hidden one included. The owner's signature policy is
    `signature_refuses`: a missing signature is the branch's, not the checkout's."""
    gitdir = Path(out(main, "rev-parse", "--absolute-git-dir") or main / ".git")
    if (gitdir / "index.lock").exists():
        return (
            f"{gitdir / 'index.lock'} exists: a git command holds the main checkout's index, or "
            "one that died left it"
        )
    # merge refreshes the index's stat data before it compares; read-tree does not, so a file
    # rewritten with the same bytes (a formatter, a build) would read as an edit
    run(main, "update-index", "-q", "--refresh")
    r = run(main, "read-tree", "-n", "-m", "-u", base_ref, new)
    if r.returncode != 0:
        return (r.stdout + r.stderr).strip() or "git read-tree refused the fast-forward"
    return ""


def signature_refuses(main: Path, base_ref: str, new: str) -> str:
    """Why the owner's merge would refuse `new` for its signature ("" when it would not, or does
    not check): the branch's own commit, so the branch's refusal."""
    if verifies_signatures(main, base_ref):
        # git's own verdict on the signature (any gpg.format, the allowed-signers file), and the
        # trust merge then asks of it
        verified = run(main, "verify-commit", new).returncode == 0
        trust = out(main, "log", "-1", "--format=%GT", new)
        floor = out(main, "config", "gpg.minTrustLevel")
        if not signature_ok(verified, trust, floor):
            return (
                f"the owner's merge verifies signatures and {new[:8]} has none it accepts "
                f"(verify-commit {'passes' if verified else 'fails'}, trust {trust or 'none'}"
                + (f", gpg.minTrustLevel {floor}" if floor else "")
                + ")"
            )
    return ""


# gpg's trust levels, lowest first, as `%GT` and `gpg.minTrustLevel` name them
TRUST_LEVELS = ("undefined", "never", "marginal", "fully", "ultimate")


def signature_ok(verified: bool, trust: str, floor: str) -> bool:
    """Merge's own rule for `--verify-signatures`: a signature git verifies (`git verify-commit`),
    trusted at or above `gpg.minTrustLevel` when that is set, else at or above marginal."""
    if not verified:
        return False
    levels = {name: i for i, name in enumerate(TRUST_LEVELS)}
    need = (floor or "marginal").lower()
    if need not in levels or trust.lower() not in levels:
        return False
    return levels[trust.lower()] >= levels[need]


def verifies_signatures(main: Path, base_ref: str) -> bool:
    """Whether the owner's `git merge` on the base verifies signatures: `merge.verifySignatures`,
    then the base branch's own `mergeOptions`, whose last `--[no-]verify-signatures` wins."""
    on = out(main, "config", "--bool", "merge.verifySignatures") == "true"
    prefix = "refs/heads/"
    branch = base_ref[len(prefix) :] if base_ref.startswith(prefix) else base_ref
    options = out(main, "config", f"branch.{branch}.mergeOptions")
    try:
        words = shlex.split(options)  # git splits it as a shell would (split_cmdline)
    except ValueError:
        words = options.split()
    for word in words:
        if word == "--verify-signatures":
            on = True
        elif word == "--no-verify-signatures":
            on = False
    return on


def added_paths(cwd: Path, spec: str) -> str:
    """Every path `spec` adds, a rename's new name included (`--no-renames` lists it as added)."""
    return out(cwd, "diff", "--name-only", "--no-renames", "--diff-filter=A", spec)


def held_files(main: Path, paths: str) -> list[str]:
    """The paths that exist in the owner's checkout as files git does not hold (an ignored `.env`),
    or that sit under such a file (`cfg/app.toml` where `cfg` is one): a fast-forward that adds them
    overwrites or deletes the owner's file."""
    held: list[str] = []
    for f in paths.splitlines():
        if not f:
            continue
        p = Path(f)
        for q in [p, *(a for a in p.parents if str(a) != ".")]:
            on_disk = main / q
            if q == p and on_disk.is_dir() and not on_disk.is_symlink():
                # a file added where the owner's checkout has a directory: git replaces the
                # directory, and every file in it git does not hold (an ignored `.env`) with it
                kept = [
                    f
                    for f in out(
                        main, "ls-files", "-z", "--others", "--", str(q)
                    ).split("\0")
                    if f
                ]
                if kept:
                    held.append(kept[0])
                    break
                continue  # it holds only what git tracks, or nothing: git replaces it
            exists = on_disk.exists() or on_disk.is_symlink()
            if q != p and on_disk.is_dir() and not on_disk.is_symlink():
                continue  # a directory above the path is no file of the owner's
            if (
                exists
                and run(main, "ls-files", "--error-unmatch", str(q)).returncode != 0
            ):
                held.append(str(q))
                break
    return held


def push_hold(main: Path) -> str:
    """The recorded push hold (`.claude/.push-hold`, unpushed-stop-guard's): while it stands, land
    and the land queue push nothing ("" when none)."""
    try:
        return (main / ".claude" / ".push-hold").read_text(encoding="utf-8").strip()
    except OSError:
        return ""


def sync_with_origin(main: Path, base: str) -> str:
    """Bring the local base up to origin's before landing, or say why not ("" when done). It only
    ever fast-forwards. Origin rewritten (its previous tip no longer in it) or a local base holding
    commits origin lacks while origin also moved are the owner's to reconcile: landing on either
    would push back what origin removed, or rebase landed history."""
    local = f"refs/heads/{base}"
    remote = f"refs/remotes/origin/{base}"
    before = out(main, "rev-parse", "--verify", "--quiet", remote)
    heads = remote_tip(main, local)
    if heads is None:
        return (
            f"REFUSING: cannot reach origin/{base}, so landing here could not be pushed and would "
            "race the agents that can. Nothing changed. Land once origin is reachable."
        )
    if not heads:
        if before:
            return (
                f"REFUSING: origin no longer has {base} (it had {before[:8]}). Nothing changed. "
                "Tell the owner."
            )
        return ""  # origin has no base yet: the push creates it
    # fetched beside the tracking ref, which moves only when origin's base still holds its previous
    # tip: a rewrite stays visible to every later land until the owner reconciles it
    # one scratch ref per land, so two lands on this machine never read each other's fetch
    fetched = f"refs/luxarch-land/{os.getpid()}-{time.time_ns()}/{base}"
    # `--refmap=`: without it git also moves the configured tracking ref on any fetch of the branch
    f = run_net(main, "fetch", "--quiet", "--refmap=", "origin", f"+{local}:{fetched}")
    tip = out(main, "rev-parse", "--verify", "--quiet", fetched)
    run(main, "update-ref", "-d", fetched)
    if f.returncode != 0 or not tip:
        return (
            f"REFUSING: cannot fetch origin/{base}. Nothing changed. Land once origin is reachable.\n"
            + (f.stdout + f.stderr).strip()
        )
    rewritten = False
    if before:
        a = run(main, "merge-base", "--is-ancestor", before, tip)
        if a.returncode not in (0, 1):
            return (
                f"REFUSING: cannot compare origin/{base} with its previous tip {before[:8]}; nothing "
                f"changed.\n{(a.stdout + a.stderr).strip()}"
            )
        rewritten = a.returncode == 1
    # moved only from the value it was read at: another land that moved it meanwhile wins, and this
    # one reads the tracking ref again below
    if not rewritten:
        run(main, "update-ref", remote, tip, *([before] if before else []))
    if rewritten:
        return (
            f"REFUSING: origin/{base} was rewritten: its previous tip {before[:8]} is no longer in "
            "it (a force-push). Landing could push back what was removed. Nothing changed. Tell "
            "the owner."
        )
    behind = count(main, f"{local}..{remote}")
    mine = count(main, f"{remote}..{local}")
    if behind and mine:
        return (
            f"REFUSING: the local {base} and origin/{base} diverged: {mine} commit(s) here are not "
            f"on origin and {behind} on origin are not here. Reconciling them is the owner's call; "
            f"nothing changed. Tell the owner, and do not rebase or reset {base}."
        )
    if behind:
        held = held_files(main, added_paths(main, f"{local}...{remote}"))
        if held:
            return (
                f"REFUSING: origin/{base} adds {', '.join(held[:5])}, which exist in the owner's "
                "checkout as files git does not hold; fast-forwarding would overwrite them. Tell "
                "the owner."
            )
        r = run(main, "merge", "--ff-only", "--no-squash", "--quiet", remote)
        if r.returncode != 0:
            return (
                f"REFUSING: fast-forward of {base} to origin/{base} failed; nothing changed.\n"
                + (r.stdout + r.stderr).strip()
            )
    return ""
